/** Names as they appear in data.ts mapped to icon keys. Names that are not listed here simply show text only. */
const alias: Record<string, string | string[]> = {
  'React': 'react', 'Angular': 'angular', 'Next.js': 'nextjs', 'TypeScript': 'typescript', 'JavaScript': 'javascript',
  'Node.js': 'nodejs', 'Tailwind CSS': 'tailwind', 'Tailwind': 'tailwind', 'Material UI': 'mui', 'MUI': 'mui',
  'GraphQL': 'graphql', 'Redis': 'redis', 'PostgreSQL': 'postgresql', 'MySQL': 'mysql', 'MongoDB': 'mongodb',
  'AWS': 'aws', 'Azure': 'azure', 'Docker': 'docker', 'Kubernetes': 'kubernetes', 'LangChain': 'langchain',
  'OpenAI API': 'openai', 'Anthropic API': 'anthropic', 'Copilot': 'copilot', 'Copilot Agents': 'copilot',
  'Copilot Agent': 'copilot', 'Copilot Agent mode': 'copilot', 'Stripe': 'stripe', 'Razorpay': 'razorpay',
  'JWT': 'jwt', 'Jasmine': 'jasmine', 'Cypress': 'cypress', 'SonarQube': 'sonarqube', 'Ionic': 'ionic',
  'RxJS': 'rxjs', 'Redux Toolkit': 'redux', 'PWA': 'pwa', 'iOS / Android': ['ios', 'android'],
  'REST': 'rest', 'REST APIs': 'rest', 'Microservices': 'microservices', 'CI/CD': 'cicd', 'Agile': 'agile', 'TDD': 'tdd',
  'Karma': 'karma', 'SSO': 'sso', 'OAuth 2.0': 'oauth', 'RAG': 'rag', 'Vector DB': 'vectordb', 'LlamaIndex': 'llamaindex',
  'NgRx': 'ngrx', 'Module Federation': 'modfed', 'Bajaj Pay SDK': 'bajajpay', 'Performance': 'performance', 'Frontend': 'frontend',
  'LLM': 'llm', 'Automation': 'automation', 'Reporting': 'reporting', 'Sync': 'sync', 'RBAC': 'rbac', 'DB indexing': 'dbindex',
  'Responsive web': 'responsive', 'Accessibility': 'a11y', 'Cross-browser': 'crossbrowser',
};

export function techIconKeys(name: string): string[] {
  const hit = alias[name];
  return hit === undefined ? [] : Array.isArray(hit) ? hit : [hit];
}
